def author_dates_exact_match(candidate: dict, birth_date, death_date) -> bool:
    """
    Whether the years of the candidate's birth/death dates exactly match the
    requested birth/death years. Both dates are required: an absent date on
    either side can not confirm (nor deny) a match, so it is not an exact match.

    :param dict candidate: Candidate OL author representation
    :param birth_date: Requested birth date
    :param death_date: Requested death date
    :rtype: bool
    """
    if not birth_date or not death_date:
        return False
    for key, wanted in (
        ('birth_date', birth_date),
        ('death_date', death_date),
    ):
        found = candidate.get(key)
        if not found:
            return False
        if extract_year(found) != extract_year(wanted):
            return False
    return True


