    """
    Whether the year of the candidate's `field` date matches the year of the
    wanted date. A date missing on either side can not confirm a match.

    :param dict candidate: Candidate OL author representation
    :param str field: Either 'birth_date' or 'death_date'
    :param wanted: The date the import supplied for that field
    :rtype: bool
    """
    if not (value := candidate.get(field)):
        return False
    wanted_year, value_year = extract_year(wanted), extract_year(value)
    return bool(wanted_year and wanted_year == value_year)


