            assert obj['location'] != obj['key']
            obj = web.ctx.site.get(obj['location'])
            seen.add(obj['key'])
        return obj

    def numeric_key(key: str) -> int:
        # A key without a number, if any, sorts first but stays deterministic.
        return int(web.numify(key) or 0)

    def search(queries) -> list:
        """
        Runs the given `queries`, returning the authors they found, deduped,
        verified against the birth and death years, and ordered by key.
        """
        keys = {
            key
            for query in queries
            for key in web.ctx.site.things(query)
            if key not in seen
        }
        authors = []
        for key in sorted(keys, key=numeric_key):
            obj = walk_redirects(web.ctx.site.get(key))
            if dates and not author_dates_exact_match(obj, birth_date, death_date):
                continue
            authors.append(obj)
        return authors

    # 1. Match on name, with the birth and death dates when they are available.
    if authors := search([build_author_query('name', name, dates)]):
        return authors

    if dates:
        # 2. Match on alternate_names, which requires both dates to match
        # exactly.
        if authors := search(
            [
                build_author_query('alternate_names', alternate_name, dates)
                for alternate_name in author.get('alternate_names') or []
                if alternate_name
            ]
        ):
            return authors

        # 3. Match on surname, which also requires both dates to match exactly.
        # The surname may be stored on its own, or be part of the name, in
        # either order: 'John Smith' or 'Smith, John'.
        surnames = [
            surname
            for surname in dict.fromkeys([author.get('surname'), find_surname(name)])
            if surname
        ]
        if surnames:
            if authors := search(
                [
                    build_author_query(field, value, dates)
                    for surname in surnames
                    for field, value in (
                        ('surname', surname),
                        ('name', f'* {surname}'),
                        ('name', f'{surname}, *'),
                    )
                ]
            ):
                return authors

    # 4. Fall back to a case-insensitive name match, either because no dates
    # were supplied, or because no author carries these exact dates.
    return [
        walk_redirects(web.ctx.site.get(key))
        for key in sorted(
            (
                key
                for key in web.ctx.site.things(build_author_query('name', name, {}))
                if key not in seen
            ),
            key=numeric_key,
        )
    ]


def find_entity(author):
    """
    Looks for an existing Author record in OL, matching on name, then on
    alternate_names, then on surname, each in combination with the birth and
    death dates of the author, and returns it if found.

    :param dict author: Author import dict {"name": "Some One"}
    :rtype: dict|None
    :return: Existing Author record, if one is found
    """
    name = author['name']
    things = find_author(author)
    et = author.get('entity_type')
    if et and et != 'person':
        if not things:
            return None
        db_entity = things[0]
        assert db_entity['type']['key'] == '/type/author'
        return db_entity
    if ', ' in name:
        things += find_author({**author, 'name': flip_name(name)})
    # Dates can only disambiguate when both of them were supplied. Otherwise the
    # match falls back to (case-insensitive) name matching alone.
    disambiguate = bool(author.get('birth_date') and author.get('death_date'))
    match = []
    seen = set()
    for a in things:
        key = a['key']
        if key in seen:
            continue
        seen.add(key)
        assert a.type.key == '/type/author'
        if disambiguate:
            if 'birth_date' in author and 'birth_date' not in a:
                continue
            if 'death_date' in author and 'death_date' not in a:
                continue
        if not author_dates_match(author, a):
            continue
        match.append(a)
    if not match:
        return None
    if len(match) == 1:
        return match[0]
    # An exact birth and death year match takes precedence over other candidates.
    exact = [
        a
        for a in match
        if author_dates_exact_match(
            a, author.get('birth_date'), author.get('death_date')
        )
    ]
    if exact:
        return min(exact, key=key_int)
    return pick_from_matches(author, match)


